-- Aprenda se Divertindo · 90 · Simulado 1 da Trilha Saúde
-- Rode depois do 89-simulado-enem-1.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o primeiro Simulado de Domingo da trilha Saúde: domingo, 25/10/2026, das 0h às 23h59.
-- 80 questões de A a E, estilo AOCP: Português, Raciocínio Lógico, Informática, Constitucional, SUS (15), Enfermagem (30), Saúde Coletiva, Fisioterapia, PcD e Igualdade Racial. 4 horas de prova.
-- Gabarito comentado liberado na segunda, às 0h. Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas nacionais, como as do Zé Gotinha, chegavam a praticamente todos os municípios, e doenças que antes lotavam hospitais tornaram-se raras. Nos últimos anos, porém, as coberturas vacinais caíram, e enfermidades que pareciam controladas voltaram a preocupar.\n\nAs causas são várias. Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos. Informações falsas circulam com rapidez nas redes sociais. Além disso, horários de funcionamento das unidades nem sempre combinam com a rotina de quem trabalha.\n\nRecuperar as coberturas exige, portanto, mais do que campanhas pontuais: é preciso aproximar a vacina das pessoas, ampliar horários, buscar quem está com o esquema atrasado e, sobretudo, reconstruir a confiança na informação científica.", "enunciado": "De acordo com o texto, a queda nas coberturas vacinais", "opcoes": ["ocorreu porque as vacinas deixaram de ser oferecidas pelo SUS.", "deve-se exclusivamente às notícias falsas nas redes sociais.", "tem causas variadas, como a percepção reduzida de risco, a desinformação e a dificuldade de acesso.", "não trouxe riscos, pois as doenças já foram erradicadas.", "é um fenômeno que atingiu apenas os grandes centros urbanos."], "gabarito": 2, "explicacao": "O segundo parágrafo começa com \"As causas são várias\" e cita a falta de contato com as doenças, a desinformação e os horários das unidades."}, {"materia": "port", "texto_base": "Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas nacionais, como as do Zé Gotinha, chegavam a praticamente todos os municípios, e doenças que antes lotavam hospitais tornaram-se raras. Nos últimos anos, porém, as coberturas vacinais caíram, e enfermidades que pareciam controladas voltaram a preocupar.\n\nAs causas são várias. Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos. Informações falsas circulam com rapidez nas redes sociais. Além disso, horários de funcionamento das unidades nem sempre combinam com a rotina de quem trabalha.\n\nRecuperar as coberturas exige, portanto, mais do que campanhas pontuais: é preciso aproximar a vacina das pessoas, ampliar horários, buscar quem está com o esquema atrasado e, sobretudo, reconstruir a confiança na informação científica.", "enunciado": "No trecho \"Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos\", a expressão \"por isso\" estabelece relação de", "opcoes": ["concessão.", "comparação.", "finalidade.", "consequência.", "oposição."], "gabarito": 3, "explicacao": "Subestimar os riscos é consequência de não ver mais as doenças de perto."}, {"materia": "port", "texto_base": "Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas nacionais, como as do Zé Gotinha, chegavam a praticamente todos os municípios, e doenças que antes lotavam hospitais tornaram-se raras. Nos últimos anos, porém, as coberturas vacinais caíram, e enfermidades que pareciam controladas voltaram a preocupar.\n\nAs causas são várias. Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos. Informações falsas circulam com rapidez nas redes sociais. Além disso, horários de funcionamento das unidades nem sempre combinam com a rotina de quem trabalha.\n\nRecuperar as coberturas exige, portanto, mais do que campanhas pontuais: é preciso aproximar a vacina das pessoas, ampliar horários, buscar quem está com o esquema atrasado e, sobretudo, reconstruir a confiança na informação científica.", "enunciado": "A palavra \"porém\", no primeiro parágrafo, poderia ser substituída, sem prejuízo de sentido, por", "opcoes": ["porque.", "conforme.", "contudo.", "portanto.", "além disso."], "gabarito": 2, "explicacao": "\"Porém\" e \"contudo\" são conjunções adversativas: introduzem uma ideia que se opõe ao sucesso descrito antes."}, {"materia": "port", "texto_base": "Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas nacionais, como as do Zé Gotinha, chegavam a praticamente todos os municípios, e doenças que antes lotavam hospitais tornaram-se raras. Nos últimos anos, porém, as coberturas vacinais caíram, e enfermidades que pareciam controladas voltaram a preocupar.\n\nAs causas são várias. Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos. Informações falsas circulam com rapidez nas redes sociais. Além disso, horários de funcionamento das unidades nem sempre combinam com a rotina de quem trabalha.\n\nRecuperar as coberturas exige, portanto, mais do que campanhas pontuais: é preciso aproximar a vacina das pessoas, ampliar horários, buscar quem está com o esquema atrasado e, sobretudo, reconstruir a confiança na informação científica.", "enunciado": "No último parágrafo, o autor", "opcoes": ["defende o fim das campanhas nacionais.", "relata a história do Zé Gotinha.", "nega a importância da ciência.", "propõe medidas para recuperar as coberturas vacinais.", "culpa exclusivamente os profissionais de saúde."], "gabarito": 3, "explicacao": "O parágrafo final apresenta propostas: aproximar a vacina das pessoas, ampliar horários, fazer busca ativa e reconstruir a confiança."}, {"materia": "port", "texto_base": "Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas nacionais, como as do Zé Gotinha, chegavam a praticamente todos os municípios, e doenças que antes lotavam hospitais tornaram-se raras. Nos últimos anos, porém, as coberturas vacinais caíram, e enfermidades que pareciam controladas voltaram a preocupar.\n\nAs causas são várias. Parte da população deixou de ver as doenças de perto e, por isso, passou a subestimar seus riscos. Informações falsas circulam com rapidez nas redes sociais. Além disso, horários de funcionamento das unidades nem sempre combinam com a rotina de quem trabalha.\n\nRecuperar as coberturas exige, portanto, mais do que campanhas pontuais: é preciso aproximar a vacina das pessoas, ampliar horários, buscar quem está com o esquema atrasado e, sobretudo, reconstruir a confiança na informação científica.", "enunciado": "No trecho \"doenças que antes lotavam hospitais tornaram-se raras\", o termo \"que\" retoma", "opcoes": ["campanhas.", "décadas.", "municípios.", "doenças.", "hospitais."], "gabarito": 3, "explicacao": "\"Que\" é pronome relativo e retoma \"doenças\": as doenças lotavam os hospitais."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que o emprego do acento indicativo de crase está correto.", "opcoes": ["A consulta foi marcada para às 10h.", "O paciente foi encaminhado à unidade de terapia intensiva.", "A enfermeira começou à medicar os pacientes.", "O técnico referiu-se à todos os casos.", "O curativo foi feito à base de soro e à gaze."], "gabarito": 1, "explicacao": "\"Encaminhar a\" + \"a unidade\" gera crase. Não há crase antes de verbo, de pronome indefinido, depois de preposição (\"para às\" está errado) nem antes de palavra masculina."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa que respeita a concordância verbal da norma-padrão.", "opcoes": ["Existe vários protocolos para esse caso.", "Houve muitas internações durante o inverno.", "Faltou medicamentos na farmácia.", "Fazem dois dias que ele está internado.", "Haviam muitos pacientes na fila."], "gabarito": 1, "explicacao": "\"Haver\" no sentido de existir é impessoal, assim como \"fazer\" indicando tempo. \"Faltar\" e \"existir\" concordam com o sujeito: \"faltaram medicamentos\", \"existem vários protocolos\"."}, {"materia": "port", "texto_base": null, "enunciado": "Na frase \"Os exames foram realizados pela equipe do laboratório\", o verbo está na voz", "opcoes": ["reflexiva.", "ativa.", "passiva analítica.", "recíproca.", "passiva sintética."], "gabarito": 2, "explicacao": "Há verbo \"ser\" + particípio (\"foram realizados\") e agente da passiva (\"pela equipe\")."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a palavra está grafada corretamente.", "opcoes": ["excessão", "esceção", "eceção", "exeção", "exceção"], "gabarito": 4, "explicacao": "A grafia correta é \"exceção\"."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa corretamente pontuada.", "opcoes": ["A enfermeira chamou, o médico plantonista.", "A enfermeira, ao perceber a queda da saturação, chamou o médico plantonista.", "A enfermeira ao perceber a queda da saturação, chamou o médico plantonista.", "A enfermeira, chamou o médico plantonista.", "O médico plantonista, avaliou o paciente."], "gabarito": 1, "explicacao": "A oração intercalada fica entre vírgulas. Não se separa o sujeito do verbo nem o verbo do complemento."}, {"materia": "rl", "texto_base": null, "enunciado": "A negação da proposição \"Todos os pacientes foram atendidos\" é:", "opcoes": ["Algum paciente foi atendido.", "Nenhum paciente deixou de ser atendido.", "Nenhum paciente foi atendido.", "Todos os pacientes não foram atendidos.", "Algum paciente não foi atendido."], "gabarito": 4, "explicacao": "A negação de \"todo\" é \"algum... não\"."}, {"materia": "rl", "texto_base": null, "enunciado": "É equivalente à proposição \"Se o paciente tem febre, então é medicado\":", "opcoes": ["O paciente tem febre e não é medicado.", "Se o paciente não é medicado, então não tem febre.", "Se o paciente não tem febre, então não é medicado.", "O paciente tem febre ou é medicado.", "Se o paciente é medicado, então tem febre."], "gabarito": 1, "explicacao": "A contrapositiva (se não q, então não p) é equivalente à condicional original."}, {"materia": "rl", "texto_base": null, "enunciado": "De quantas formas é possível escolher 3 enfermeiros, entre 6 disponíveis, para compor uma escala de plantão, sem distinção de funções?", "opcoes": ["36", "120", "216", "18", "20"], "gabarito": 4, "explicacao": "Combinação: C(6,3) = 6 × 5 × 4 ÷ 6 = 20. O valor 120 seria o arranjo, em que a ordem importa."}, {"materia": "rl", "texto_base": null, "enunciado": "Na sequência 3, 7, 15, 31, 63, …, o próximo termo é", "opcoes": ["99", "126", "127", "125", "95"], "gabarito": 2, "explicacao": "Cada termo é o dobro do anterior mais 1: 63 × 2 + 1 = 127."}, {"materia": "rl", "texto_base": null, "enunciado": "Um hospital tinha 240 leitos e ampliou esse número em 15%. Passou a ter", "opcoes": ["36 leitos.", "255 leitos.", "264 leitos.", "276 leitos.", "290 leitos."], "gabarito": 3, "explicacao": "15% de 240 = 36. 240 + 36 = 276."}, {"materia": "inf", "texto_base": null, "enunciado": "No Windows, o atalho de teclado usado para copiar um item selecionado é", "opcoes": ["Ctrl + X", "Ctrl + Z", "Ctrl + V", "Ctrl + C", "Ctrl + P"], "gabarito": 3, "explicacao": "Ctrl + C copia, Ctrl + V cola, Ctrl + X recorta, Ctrl + Z desfaz e Ctrl + P imprime."}, {"materia": "inf", "texto_base": null, "enunciado": "Ao enviar um e-mail, os endereços colocados no campo CCO", "opcoes": ["recebem a mensagem sem que os demais destinatários vejam seus endereços.", "não recebem a mensagem.", "são bloqueados pelo servidor.", "recebem apenas o assunto da mensagem.", "aparecem para todos os destinatários."], "gabarito": 0, "explicacao": "CCO significa \"com cópia oculta\". É útil para proteger a privacidade dos destinatários."}, {"materia": "inf", "texto_base": null, "enunciado": "Em uma planilha eletrônica, a fórmula =SOMA(A1:A4), com os valores 10, 20, 30 e 40 nas células A1 a A4, retorna", "opcoes": ["10", "40", "25", "4", "100"], "gabarito": 4, "explicacao": "10 + 20 + 30 + 40 = 100. A média seria 25."}, {"materia": "inf", "texto_base": null, "enunciado": "Um programa malicioso que se propaga automaticamente pela rede, explorando falhas, sem precisar de um arquivo hospedeiro, é o", "opcoes": ["spyware.", "cavalo de troia.", "worm.", "firewall.", "adware."], "gabarito": 2, "explicacao": "O worm se replica sozinho pela rede. O cavalo de troia se disfarça de programa legítimo, e o firewall é uma ferramenta de proteção."}, {"materia": "inf", "texto_base": null, "enunciado": "Para proteger dados de prontuários contra perda em caso de falha no computador, a medida mais adequada é", "opcoes": ["fazer cópias de segurança (backup) periódicas.", "desativar as atualizações do sistema.", "desligar o antivírus.", "compartilhar a senha com a equipe.", "salvar tudo apenas na área de trabalho."], "gabarito": 0, "explicacao": "O backup garante a recuperação dos dados. Compartilhar senha e desativar proteções aumentam os riscos."}, {"materia": "const", "texto_base": null, "enunciado": "Segundo a Constituição Federal, a saúde é", "opcoes": ["serviço prestado somente mediante pagamento.", "direito apenas dos trabalhadores com carteira assinada.", "responsabilidade apenas dos municípios.", "dever exclusivo da família.", "direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas."], "gabarito": 4, "explicacao": "CF, art. 196."}, {"materia": "const", "texto_base": null, "enunciado": "Pela Constituição, as instituições privadas podem participar do SUS de forma complementar, tendo preferência", "opcoes": ["as farmácias.", "as entidades filantrópicas e as sem fins lucrativos.", "as empresas estrangeiras.", "os planos de saúde.", "as empresas com maior lucro."], "gabarito": 1, "explicacao": "CF, art. 199, § 1º. O § 3º veda a participação direta ou indireta de capital estrangeiro, salvo nos casos previstos em lei."}, {"materia": "sus", "texto_base": null, "enunciado": "Segundo a Constituição Federal, as ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as diretrizes de", "opcoes": ["hierarquia militar, disciplina e obediência.", "descentralização, atendimento integral e participação da comunidade.", "privatização, lucro e eficiência.", "centralização, atendimento seletivo e gestão privada.", "cobrança de taxas, seletividade e filantropia."], "gabarito": 1, "explicacao": "CF, art. 198."}, {"materia": "sus", "texto_base": null, "enunciado": "A lei que dispõe sobre as condições para a promoção, proteção e recuperação da saúde e sobre a organização e o funcionamento dos serviços é a", "opcoes": ["Lei 13.146/2015.", "Lei 7.498/1986.", "Lei 8.080/1990.", "Lei 8.666/1993.", "Lei 8.142/1990."], "gabarito": 2, "explicacao": "A Lei 8.080/1990 é a Lei Orgânica da Saúde. A Lei 8.142/1990 trata da participação da comunidade e das transferências de recursos."}, {"materia": "sus", "texto_base": null, "enunciado": "Segundo a Lei 8.080/1990, a integralidade de assistência é entendida como", "opcoes": ["atendimento restrito a doenças crônicas.", "oferta de serviços somente a quem contribui para a previdência.", "atendimento exclusivo na atenção primária.", "atendimento apenas de urgência e emergência.", "conjunto articulado e contínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade."], "gabarito": 4, "explicacao": "Lei 8.080/1990, art. 7º, II."}, {"materia": "sus", "texto_base": null, "enunciado": "Pela Lei 8.142/1990, as instâncias colegiadas do SUS em cada esfera de governo são", "opcoes": ["o Ministério e as secretarias de saúde.", "a Anvisa e a ANS.", "os hospitais universitários e as UPAs.", "a Conferência de Saúde e o Conselho de Saúde.", "a Câmara e o Senado."], "gabarito": 3, "explicacao": "Lei 8.142/1990, art. 1º."}, {"materia": "sus", "texto_base": null, "enunciado": "Segundo a Lei 8.142/1990, a Conferência de Saúde reúne-se", "opcoes": ["anualmente, só com médicos.", "a cada dois anos, só com gestores.", "uma única vez.", "todo mês.", "a cada quatro anos, com representação dos vários segmentos sociais."], "gabarito": 4, "explicacao": "Lei 8.142/1990, art. 1º, § 1º. Ela avalia a situação de saúde e propõe diretrizes para a política de saúde."}, {"materia": "sus", "texto_base": null, "enunciado": "Nos Conselhos e Conferências de Saúde, a representação dos usuários deve ser", "opcoes": ["de no máximo 10% dos membros.", "paritária em relação ao conjunto dos demais segmentos.", "definida pelo prefeito, sem regra.", "maioria absoluta de dois terços.", "inexistente."], "gabarito": 1, "explicacao": "Lei 8.142/1990, art. 1º, § 4º. Na prática, os usuários ocupam 50% das vagas."}, {"materia": "sus", "texto_base": null, "enunciado": "Segundo o Decreto 7.508/2011, são Portas de Entrada às ações e aos serviços de saúde nas Redes de Atenção à Saúde os serviços", "opcoes": ["somente das clínicas particulares conveniadas.", "apenas dos hospitais de alta complexidade.", "apenas dos consultórios de especialistas.", "exclusivamente dos laboratórios.", "de atenção primária, de urgência e emergência, de atenção psicossocial e especiais de acesso aberto."], "gabarito": 4, "explicacao": "Decreto 7.508/2011, art. 9º."}, {"materia": "sus", "texto_base": null, "enunciado": "O Decreto 7.508/2011 define Região de Saúde como", "opcoes": ["espaço geográfico contínuo constituído por agrupamentos de municípios limítrofes, com identidades culturais, econômicas e sociais e redes de comunicação e transporte compartilhadas.", "o território de um único bairro.", "a área de atuação de um hospital privado.", "o conjunto dos estados de uma macrorregião do IBGE.", "a área de abrangência de um plano de saúde."], "gabarito": 0, "explicacao": "Decreto 7.508/2011, art. 2º, I."}, {"materia": "sus", "texto_base": null, "enunciado": "A relação de medicamentos ofertados no âmbito do SUS, prevista no Decreto 7.508/2011, é a", "opcoes": ["RENASES.", "SIM.", "SINAN.", "CNES.", "RENAME."], "gabarito": 4, "explicacao": "RENAME é a Relação Nacional de Medicamentos Essenciais. A RENASES é a relação de ações e serviços de saúde."}, {"materia": "sus", "texto_base": null, "enunciado": "Na Estratégia Saúde da Família, a equipe mínima é composta por", "opcoes": ["dentista e farmacêutico, apenas.", "enfermeiro e psicólogo, apenas.", "médico especialista e fisioterapeuta.", "médico, enfermeiro, auxiliar ou técnico de enfermagem e agentes comunitários de saúde.", "apenas médico e enfermeiro."], "gabarito": 3, "explicacao": "PNAB (Portaria 2.436/2017). Podem ser acrescentados profissionais de saúde bucal e agentes de combate às endemias."}, {"materia": "sus", "texto_base": null, "enunciado": "Na Atenção Básica, o agente comunitário de saúde tem como atribuição característica", "opcoes": ["emitir laudos de exames de imagem.", "chefiar a equipe médica.", "realizar cirurgias ambulatoriais.", "realizar visitas domiciliares e cadastrar as famílias do seu território.", "prescrever medicamentos controlados."], "gabarito": 3, "explicacao": "Visita domiciliar e cadastro das famílias são atribuições do ACS. Prescrição, cirurgia e laudo são atos de outros profissionais."}, {"materia": "sus", "texto_base": null, "enunciado": "O sistema de informação usado para registrar as doenças e agravos de notificação compulsória é o", "opcoes": ["SIM.", "SINAN.", "SIH.", "SINASC.", "SIA."], "gabarito": 1, "explicacao": "SINAN: Sistema de Informação de Agravos de Notificação. O SIM registra óbitos, o SINASC nascidos vivos e o SIH internações."}, {"materia": "sus", "texto_base": null, "enunciado": "A Lei 8.080/1990 inclui no campo de atuação do SUS a vigilância epidemiológica, entendida como o conjunto de ações que", "opcoes": ["trata exclusivamente da saúde do trabalhador.", "fiscaliza apenas alimentos e medicamentos.", "proporciona o conhecimento, a detecção ou a prevenção de qualquer mudança nos fatores determinantes e condicionantes da saúde, para recomendar medidas de prevenção e controle das doenças.", "realiza somente a compra de vacinas.", "cuida apenas do saneamento básico."], "gabarito": 2, "explicacao": "Lei 8.080/1990, art. 6º, § 2º. A fiscalização de produtos é da vigilância sanitária (§ 1º)."}, {"materia": "sus", "texto_base": null, "enunciado": "O princípio doutrinário do SUS que orienta tratar de forma desigual os desiguais, priorizando quem mais precisa, é a", "opcoes": ["equidade.", "descentralização.", "regionalização.", "universalidade.", "hierarquização."], "gabarito": 0, "explicacao": "A equidade busca reduzir desigualdades, investindo mais onde a necessidade é maior."}, {"materia": "sus", "texto_base": null, "enunciado": "O controle social no SUS é exercido principalmente por meio", "opcoes": ["dos laboratórios privados.", "dos conselhos de classe profissional, exclusivamente.", "das forças armadas.", "dos Conselhos e das Conferências de Saúde.", "das empresas de planos de saúde."], "gabarito": 3, "explicacao": "Lei 8.142/1990. Os conselhos de classe, como o Cofen, fiscalizam o exercício profissional, não a política de saúde."}, {"materia": "enf", "texto_base": null, "enunciado": "Segundo a Lei 7.498/1986, é atividade privativa do enfermeiro", "opcoes": ["a administração de medicamentos por via oral.", "a consulta de enfermagem.", "a higiene do paciente.", "a mudança de decúbito.", "a verificação de sinais vitais."], "gabarito": 1, "explicacao": "Lei 7.498/1986, art. 11, I, i. Também são privativos a prescrição da assistência de enfermagem e os cuidados de maior complexidade técnica a pacientes graves."}, {"materia": "enf", "texto_base": null, "enunciado": "Segundo a Lei 7.498/1986, os cuidados diretos de enfermagem a pacientes graves com risco de vida são privativos do", "opcoes": ["enfermeiro.", "médico.", "auxiliar de enfermagem.", "técnico de enfermagem.", "fisioterapeuta."], "gabarito": 0, "explicacao": "Lei 7.498/1986, art. 11, I, l."}, {"materia": "enf", "texto_base": null, "enunciado": "O processo de enfermagem é organizado em etapas inter-relacionadas. A etapa em que se verificam as mudanças nas respostas da pessoa e se decide sobre a continuidade ou mudança das ações é a", "opcoes": ["alta administrativa.", "admissão hospitalar.", "evolução de enfermagem.", "anamnese.", "prescrição médica."], "gabarito": 2, "explicacao": "A evolução (avaliação dos resultados) fecha o ciclo do processo de enfermagem e realimenta as demais etapas."}, {"materia": "enf", "texto_base": null, "enunciado": "Um adulto em repouso apresenta frequência cardíaca de 115 batimentos por minuto. Esse achado é chamado de", "opcoes": ["taquipneia.", "taquicardia.", "bradicardia.", "normocardia.", "bradipneia."], "gabarito": 1, "explicacao": "Em adultos, a FC normal em repouso fica entre 60 e 100 bpm. Acima de 100 bpm é taquicardia."}, {"materia": "enf", "texto_base": null, "enunciado": "A frequência respiratória de 28 incursões por minuto em um adulto em repouso caracteriza", "opcoes": ["bradipneia.", "apneia.", "eupneia.", "taquipneia.", "dispneia paroxística noturna."], "gabarito": 3, "explicacao": "A FR normal do adulto fica em torno de 12 a 20 irpm. Valores acima são taquipneia."}, {"materia": "enf", "texto_base": "Paciente adulto, 70 kg, internado em clínica médica, com prescrição de soro fisiológico 0,9% 1.000 mL para correr em 8 horas, em equipo macrogotas.", "enunciado": "Quantas gotas por minuto devem ser infundidas?", "opcoes": ["Aproximadamente 42 gotas/min.", "Aproximadamente 63 gotas/min.", "Aproximadamente 14 gotas/min.", "Aproximadamente 21 gotas/min.", "Aproximadamente 125 gotas/min."], "gabarito": 0, "explicacao": "Macrogotas: gotas/min = V ÷ (T × 3) = 1.000 ÷ (8 × 3) = 1.000 ÷ 24 ≈ 41,7, ou cerca de 42 gotas/min. 125 seria o valor em mL/h."}, {"materia": "enf", "texto_base": "Paciente adulto, 70 kg, internado em clínica médica, com prescrição de soro fisiológico 0,9% 1.000 mL para correr em 8 horas, em equipo macrogotas.", "enunciado": "Se a mesma prescrição fosse instalada em bomba de infusão, a vazão programada seria de", "opcoes": ["125 mL/h.", "42 mL/h.", "250 mL/h.", "8 mL/h.", "100 mL/h."], "gabarito": 0, "explicacao": "1.000 mL ÷ 8 h = 125 mL/h."}, {"materia": "enf", "texto_base": null, "enunciado": "Devem ser infundidos 300 mL de soro em 6 horas, em equipo de microgotas. O gotejamento será de", "opcoes": ["25 microgotas/min.", "50 microgotas/min.", "150 microgotas/min.", "17 microgotas/min.", "300 microgotas/min."], "gabarito": 1, "explicacao": "Microgotas: gotas/min = V ÷ T (em horas) = 300 ÷ 6 = 50."}, {"materia": "enf", "texto_base": null, "enunciado": "Foram prescritos 250 mg de um antibiótico. O frasco disponível contém 500 mg em 5 mL. O volume a ser administrado é", "opcoes": ["10 mL.", "2,5 mL.", "1,25 mL.", "5 mL.", "0,5 mL."], "gabarito": 1, "explicacao": "500 mg ─ 5 mL; 250 mg ─ x. x = 250 × 5 ÷ 500 = 2,5 mL."}, {"materia": "enf", "texto_base": null, "enunciado": "Uma criança de 20 kg tem prescrição de 15 mg/kg de um medicamento por dose. A dose a ser administrada é", "opcoes": ["1,33 mg.", "150 mg.", "200 mg.", "35 mg.", "300 mg."], "gabarito": 4, "explicacao": "15 mg × 20 kg = 300 mg."}, {"materia": "enf", "texto_base": null, "enunciado": "Foram prescritas 20 UI de insulina regular. Usando insulina com concentração de 100 UI/mL e seringa graduada em mL, o volume a ser aspirado é", "opcoes": ["0,2 mL.", "0,5 mL.", "20 mL.", "2 mL.", "0,02 mL."], "gabarito": 0, "explicacao": "100 UI ─ 1 mL; 20 UI ─ x. x = 20 ÷ 100 = 0,2 mL."}, {"materia": "enf", "texto_base": null, "enunciado": "Quantos gramas de glicose há em 500 mL de soro glicosado a 5%?", "opcoes": ["25 g.", "50 g.", "100 g.", "5 g.", "2,5 g."], "gabarito": 0, "explicacao": "5% significa 5 g em 100 mL. Em 500 mL: 5 × 5 = 25 g."}, {"materia": "enf", "texto_base": null, "enunciado": "Em 24 horas, um paciente recebeu 2.500 mL entre soro, dieta e água e eliminou 2.100 mL entre diurese, drenos e perdas estimadas. O balanço hídrico foi", "opcoes": ["zerado.", "negativo em 2.100 mL.", "positivo em 4.600 mL.", "positivo em 400 mL.", "negativo em 400 mL."], "gabarito": 3, "explicacao": "Balanço = entradas − saídas = 2.500 − 2.100 = +400 mL."}, {"materia": "enf", "texto_base": null, "enunciado": "A vacina BCG é administrada por via", "opcoes": ["oral.", "intramuscular.", "endovenosa.", "subcutânea.", "intradérmica."], "gabarito": 4, "explicacao": "A BCG é aplicada por via intradérmica, em regra na inserção inferior do músculo deltoide direito."}, {"materia": "enf", "texto_base": null, "enunciado": "Na rede de frio, as vacinas de uso rotineiro na sala de vacinação devem ser conservadas entre", "opcoes": ["+2 °C e +8 °C.", "−20 °C e −10 °C.", "+15 °C e +25 °C.", "+10 °C e +15 °C.", "0 °C e +2 °C."], "gabarito": 0, "explicacao": "Manual de Rede de Frio do Ministério da Saúde: a temperatura ideal é em torno de +5 °C, dentro da faixa de +2 °C a +8 °C."}, {"materia": "enf", "texto_base": null, "enunciado": "Segundo a OMS, são momentos para a higiene das mãos, entre outros,", "opcoes": ["somente após retirar as luvas.", "apenas ao chegar e ao sair do plantão.", "só quando as mãos estiverem visivelmente sujas.", "antes de tocar o paciente e após o risco de exposição a fluidos corporais.", "apenas antes de procedimentos cirúrgicos."], "gabarito": 3, "explicacao": "Os cinco momentos são: antes de tocar o paciente, antes de procedimento limpo ou asséptico, após risco de exposição a fluidos, após tocar o paciente e após tocar superfícies próximas a ele."}, {"materia": "enf", "texto_base": null, "enunciado": "Para um paciente com suspeita de tuberculose pulmonar bacilífera, além das precauções padrão, devem ser adotadas precauções para", "opcoes": ["contato apenas, com avental e luvas.", "nenhuma precaução adicional.", "aerossóis, com máscara N95 (PFF2) para o profissional e quarto privativo.", "contato e uso de óculos, apenas.", "gotículas, com máscara cirúrgica para o profissional."], "gabarito": 2, "explicacao": "A tuberculose é transmitida por aerossóis. O ideal é quarto privativo com pressão negativa. Para o paciente, em transporte, usa-se máscara cirúrgica."}, {"materia": "enf", "texto_base": null, "enunciado": "Pela classificação de Spaulding, os artigos que entram em contato com tecidos estéreis ou com o sistema vascular, como instrumentais cirúrgicos, são classificados como", "opcoes": ["não críticos, exigindo desinfecção de baixo nível.", "críticos, devendo ser esterilizados.", "semicríticos, exigindo apenas limpeza.", "semicríticos, exigindo esterilização obrigatória.", "não críticos, dispensando qualquer processamento."], "gabarito": 1, "explicacao": "Críticos exigem esterilização. Semicríticos (mucosas) exigem no mínimo desinfecção de alto nível, e não críticos (pele íntegra), limpeza ou desinfecção de baixo nível."}, {"materia": "enf", "texto_base": null, "enunciado": "Na escala de coma de Glasgow, são avaliados", "opcoes": ["força muscular, reflexos e sensibilidade.", "dor, ansiedade e sono.", "pressão arterial, pulso e temperatura.", "saturação, frequência respiratória e cor da pele.", "abertura ocular, resposta verbal e resposta motora."], "gabarito": 4, "explicacao": "A pontuação vai de 3 a 15. Valores iguais ou menores que 8 indicam, em geral, coma grave."}, {"materia": "enf", "texto_base": null, "enunciado": "Na lesão por pressão estágio 1, observa-se", "opcoes": ["ferida com túneis e descolamentos.", "perda total da espessura da pele com exposição de osso.", "pele íntegra com eritema que não embranquece à pressão.", "bolha rompida com exposição de tendão.", "necrose extensa com tecido escuro."], "gabarito": 2, "explicacao": "Classificação NPUAP/NPIAP: no estágio 1 a pele está íntegra, com eritema não branqueável. Os estágios seguintes envolvem perda progressiva de tecido."}, {"materia": "enf", "texto_base": null, "enunciado": "A escala de Braden é usada pela enfermagem para avaliar o risco de", "opcoes": ["infecção urinária.", "trombose venosa profunda.", "queda do leito.", "desenvolvimento de lesão por pressão.", "dor no pós-operatório."], "gabarito": 3, "explicacao": "Ela avalia percepção sensorial, umidade, atividade, mobilidade, nutrição e fricção/cisalhamento. Quanto menor a pontuação, maior o risco."}, {"materia": "enf", "texto_base": null, "enunciado": "Na ressuscitação cardiopulmonar de um adulto, sem via aérea avançada, a relação entre compressões e ventilações recomendada é", "opcoes": ["10 compressões para 2 ventilações.", "5 compressões para 1 ventilação.", "30 compressões para 1 ventilação.", "30 compressões para 2 ventilações.", "15 compressões para 2 ventilações."], "gabarito": 3, "explicacao": "Diretrizes da AHA: 30:2, com 100 a 120 compressões por minuto e profundidade de 5 a 6 cm."}, {"materia": "enf", "texto_base": null, "enunciado": "Para medir a sonda nasogástrica antes da inserção em adultos, a técnica usual considera a distância", "opcoes": ["do queixo ao joelho.", "da testa ao ombro.", "da ponta do nariz ao lóbulo da orelha e daí ao apêndice xifoide.", "da boca ao umbigo.", "da orelha ao cotovelo."], "gabarito": 2, "explicacao": "A medida nariz–lóbulo da orelha–apêndice xifoide estima o comprimento até o estômago. A confirmação mais segura do posicionamento é a radiografia."}, {"materia": "enf", "texto_base": null, "enunciado": "A posição em que o paciente fica em decúbito dorsal com a cabeceira elevada entre 45° e 60° é a de", "opcoes": ["Fowler.", "Sims.", "litotomia.", "genupeitoral.", "Trendelenburg."], "gabarito": 0, "explicacao": "Na Trendelenburg, a cabeça fica mais baixa que os pés. Sims é o decúbito lateral esquerdo com a perna direita fletida."}, {"materia": "enf", "texto_base": null, "enunciado": "Uma gestante teve a data da última menstruação em 10 de março de 2026. Pela regra de Naegele, a data provável do parto é", "opcoes": ["3 de dezembro de 2026.", "7 de dezembro de 2026.", "17 de janeiro de 2027.", "10 de dezembro de 2026.", "17 de dezembro de 2026."], "gabarito": 4, "explicacao": "Regra de Naegele: soma-se 7 dias ao dia e subtrai-se 3 meses do mês (ou soma-se 9). 10 + 7 = 17; março − 3 = dezembro."}, {"materia": "enf", "texto_base": null, "enunciado": "Um adulto pesa 80 kg e mede 1,60 m. Seu índice de massa corporal (IMC) é de aproximadamente", "opcoes": ["20 kg/m², compatível com peso normal.", "50 kg/m², compatível com obesidade grave.", "28 kg/m², compatível com sobrepeso.", "31,3 kg/m², compatível com obesidade.", "25 kg/m², compatível com peso normal."], "gabarito": 3, "explicacao": "IMC = 80 ÷ 1,60² = 80 ÷ 2,56 ≈ 31,25. Pela OMS, IMC ≥ 30 indica obesidade."}, {"materia": "enf", "texto_base": null, "enunciado": "Diante de um paciente com reação anafilática grave, com dificuldade respiratória e hipotensão, o medicamento de primeira escolha é a", "opcoes": ["insulina regular.", "vitamina C endovenosa.", "adrenalina por via intramuscular.", "dipirona por via oral.", "furosemida por via oral."], "gabarito": 2, "explicacao": "A adrenalina IM, em geral na face anterolateral da coxa, é o tratamento de primeira linha na anafilaxia."}, {"materia": "enf", "texto_base": null, "enunciado": "Segundo o Código de Ética dos Profissionais de Enfermagem, o profissional deve", "opcoes": ["manter sigilo sobre o que souber em razão da atividade profissional, ressalvados os casos previstos em lei.", "assinar procedimentos realizados por outro profissional.", "divulgar o diagnóstico do paciente nas redes sociais.", "recusar atendimento em urgência por motivo pessoal.", "executar qualquer prescrição, mesmo sabendo que causará dano."], "gabarito": 0, "explicacao": "Resolução Cofen 564/2017. O sigilo pode ser quebrado em situações previstas em lei, por ordem judicial ou com consentimento do paciente."}, {"materia": "enf", "texto_base": null, "enunciado": "É sinal típico de hipoglicemia:", "opcoes": ["hálito cetônico com respiração de Kussmaul.", "poliúria e polidipsia.", "sudorese fria, tremores e confusão mental.", "febre alta e calafrios.", "pele seca e quente, com sede intensa."], "gabarito": 2, "explicacao": "Os sinais adrenérgicos (sudorese, tremor, taquicardia) e os neuroglicopênicos (confusão) são típicos. Hálito cetônico, sede e poliúria sugerem hiperglicemia."}, {"materia": "enf", "texto_base": null, "enunciado": "Na administração de medicamentos por via intramuscular em adultos, a região ventroglútea (de Hochstetter) é considerada segura porque", "opcoes": ["fica próxima ao nervo ciático.", "fica distante de grandes vasos e nervos e tem boa massa muscular.", "permite injetar qualquer volume sem limite.", "é indicada apenas para vacinas orais.", "é a única região que dispensa antissepsia."], "gabarito": 1, "explicacao": "A ventroglútea tem musculatura espessa (glúteos médio e mínimo) e está longe do nervo ciático e de grandes vasos."}, {"materia": "med", "texto_base": null, "enunciado": "Em epidemiologia, a incidência de uma doença corresponde", "opcoes": ["aos casos novos em uma população durante um período.", "aos óbitos pela doença.", "ao número de leitos ocupados.", "aos casos curados.", "a todos os casos existentes em determinado momento."], "gabarito": 0, "explicacao": "A prevalência considera todos os casos existentes (novos e antigos) em um momento ou período."}, {"materia": "med", "texto_base": null, "enunciado": "Em um município de 10.000 habitantes, foram registrados 50 casos novos de uma doença em um ano. A incidência foi de", "opcoes": ["0,5 caso por 1.000 habitantes.", "20 casos por 1.000 habitantes.", "5 casos por 1.000 habitantes.", "5 casos por 100 habitantes.", "50 casos por 1.000 habitantes."], "gabarito": 2, "explicacao": "50 ÷ 10.000 = 0,005 = 5 por 1.000 habitantes (ou 500 por 100.000)."}, {"materia": "med", "texto_base": null, "enunciado": "Quando uma doença apresenta aumento de casos acima do esperado em uma região, em determinado período, ocorre", "opcoes": ["uma pandemia, sempre.", "uma endemia.", "um caso esporádico.", "uma erradicação.", "uma epidemia."], "gabarito": 4, "explicacao": "Endemia é a ocorrência habitual e esperada. Pandemia é a epidemia que se espalha por vários países e continentes."}, {"materia": "med", "texto_base": null, "enunciado": "O rastreamento de câncer de colo do útero com exame citopatológico é exemplo de prevenção", "opcoes": ["quaternária.", "terciária.", "primária.", "primordial.", "secundária."], "gabarito": 4, "explicacao": "A prevenção secundária busca a detecção precoce. Vacinar contra o HPV seria prevenção primária. A quaternária evita intervenções desnecessárias."}, {"materia": "med", "texto_base": null, "enunciado": "A prevenção quaternária tem como objetivo", "opcoes": ["reabilitar pacientes com sequelas.", "evitar intervenções médicas desnecessárias e o excesso de exames e tratamentos.", "diagnosticar doenças precocemente.", "vacinar a população.", "tratar doenças agudas."], "gabarito": 1, "explicacao": "O conceito busca proteger o paciente da medicalização excessiva e de danos causados pelo próprio cuidado (iatrogenia)."}, {"materia": "med", "texto_base": null, "enunciado": "Segundo as diretrizes brasileiras, o diagnóstico de diabetes mellitus pode ser feito com glicemia de jejum igual ou superior a", "opcoes": ["99 mg/dL.", "126 mg/dL, confirmada em nova medida.", "200 mg/dL em jejum, obrigatoriamente.", "70 mg/dL.", "110 mg/dL em uma única medida."], "gabarito": 1, "explicacao": "Glicemia de jejum ≥ 126 mg/dL, HbA1c ≥ 6,5% ou glicemia de 2 horas no TOTG ≥ 200 mg/dL, confirmadas em nova medida na ausência de sintomas inequívocos."}, {"materia": "med", "texto_base": null, "enunciado": "A sensibilidade de um teste diagnóstico é a capacidade de", "opcoes": ["identificar corretamente os doentes (verdadeiros positivos).", "identificar corretamente os sadios.", "ser barato e rápido.", "dar sempre o mesmo resultado.", "prever o tempo de cura."], "gabarito": 0, "explicacao": "Sensibilidade = VP ÷ (VP + FN). A especificidade identifica corretamente os não doentes."}, {"materia": "fisio", "texto_base": null, "enunciado": "Na escala de força muscular de 0 a 5 (MRC), o grau 3 corresponde a", "opcoes": ["força normal contra resistência máxima.", "apenas contração visível, sem movimento.", "movimento somente com a gravidade eliminada.", "movimento completo contra a gravidade, sem resistência adicional.", "ausência de contração."], "gabarito": 3, "explicacao": "Grau 0 = sem contração; 1 = contração sem movimento; 2 = movimento sem gravidade; 3 = vence a gravidade; 4 = vence alguma resistência; 5 = normal."}, {"materia": "fisio", "texto_base": null, "enunciado": "A goniometria é utilizada na avaliação fisioterapêutica para medir", "opcoes": ["a densidade óssea.", "a capacidade pulmonar.", "a força muscular.", "a frequência cardíaca.", "a amplitude de movimento das articulações."], "gabarito": 4, "explicacao": "O goniômetro mede ângulos articulares em graus."}, {"materia": "fisio", "texto_base": null, "enunciado": "O incentivador respiratório (espirometria de incentivo) é usado no pós-operatório principalmente para", "opcoes": ["reduzir a força muscular.", "aspirar secreções.", "estimular inspirações profundas e prevenir atelectasias.", "medir a pressão arterial.", "aumentar a frequência cardíaca."], "gabarito": 2, "explicacao": "A inspiração profunda e sustentada ajuda a reexpandir os alvéolos, reduzindo complicações pulmonares."}, {"materia": "fisio", "texto_base": null, "enunciado": "A cinesioterapia é o recurso fisioterapêutico que utiliza", "opcoes": ["o movimento e o exercício terapêutico.", "a corrente elétrica.", "o calor profundo.", "medicamentos injetáveis.", "a água em piscina, exclusivamente."], "gabarito": 0, "explicacao": "Cinesioterapia é a terapia pelo movimento. Eletroterapia, termoterapia e hidroterapia são outros recursos."}, {"materia": "pcd", "texto_base": null, "enunciado": "Segundo a Lei Brasileira de Inclusão (Lei 13.146/2015), considera-se pessoa com deficiência aquela que tem", "opcoes": ["idade superior a 60 anos.", "qualquer doença temporária.", "impedimento de longo prazo de natureza física, mental, intelectual ou sensorial que, em interação com barreiras, pode obstruir sua participação plena na sociedade.", "baixa escolaridade.", "renda familiar baixa."], "gabarito": 2, "explicacao": "Lei 13.146/2015, art. 2º."}, {"materia": "igual", "texto_base": null, "enunciado": "Segundo o Estatuto da Igualdade Racial (Lei 12.288/2010), a população negra é o conjunto de pessoas que se autodeclaram", "opcoes": ["pretas e pardas, conforme o quesito cor ou raça do IBGE.", "indígenas.", "apenas pretas.", "amarelas.", "de qualquer cor, desde que residentes no Brasil."], "gabarito": 0, "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, IV."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('saude', date '2026-10-25', 'Simulado 1 · Saúde', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'saude' and s.data = date '2026-10-25' group by s.id;
